migration.sql:
BEGIN;

-- Refuse the whole migration before changing any row if a historical approved
-- fee is invalid. Keep the offending ids in the exception for operators.
DO $migration$
DECLARE
  invalid_ids text;
BEGIN
  SELECT string_agg(s.id, ', ' ORDER BY s.id)
    INTO invalid_ids
    FROM subscription AS s
   WHERE s.terms ? 'monthlyFeeCents'
     AND (s.terms->>'monthlyFeeCents') ~ '^-?[0-9]+$'
     AND (s.terms->>'monthlyFeeCents')::numeric < 0;

  IF invalid_ids IS NOT NULL THEN
    RAISE EXCEPTION 'negative approved monthly fee for subscription(s): %', invalid_ids
      USING ERRCODE = 'P0001';
  END IF;
END
$migration$;

CREATE TABLE IF NOT EXISTS pricing_history (
  subscription_id text NOT NULL REFERENCES subscription(id),
  effective_from date NOT NULL,
  fee_cents integer NOT NULL CHECK (fee_cents >= 0),
  PRIMARY KEY (subscription_id, effective_from)
);

CREATE TABLE IF NOT EXISTS pricing_decision (
  subscription_id text PRIMARY KEY REFERENCES subscription(id),
  fee_cents integer NOT NULL CHECK (fee_cents >= 0)
);

-- approved_at is the date on which the fee decision was made. Preserve every
-- subscription and its original terms while recording the fee separately.
INSERT INTO pricing_history(subscription_id, effective_from, fee_cents)
SELECT s.id, s.approved_at, (s.terms->>'monthlyFeeCents')::integer
  FROM subscription AS s
 WHERE s.terms ? 'monthlyFeeCents'
   AND (s.terms->>'monthlyFeeCents') ~ '^[0-9]+$'
ON CONFLICT (subscription_id, effective_from) DO NOTHING;

INSERT INTO pricing_decision(subscription_id, fee_cents)
SELECT DISTINCT ON (subscription_id) subscription_id, fee_cents
  FROM pricing_history
 ORDER BY subscription_id, effective_from DESC
ON CONFLICT (subscription_id) DO UPDATE SET fee_cents = EXCLUDED.fee_cents;

COMMIT;

