import {test,expect} from 'bun:test';
import {getFee,newVersion,acceptLegacyTerms} from './subscriptions';

test('new decision',()=>expect(getFee({terms:{},pricingDecision:{feeCents:2500}})).toBe(2500));
test('next version needs a new fee decision',()=>{
  const next = newVersion({terms:{monthlyFeeCents:2500,plan:'basic'},pricingDecision:{feeCents:2500}});
  expect(next).toEqual({terms:{plan:'basic'},pricingDecision:null});
  expect(getFee(next)).toBe(100);
});
test('legacy monthly fee wire field remains accepted',()=>expect(acceptLegacyTerms({monthlyFeeCents:2500})).toEqual({monthlyFeeCents:2500}));

subscriptions.ts:
export const MIN_FEE = 100;

type Subscription = {
  terms?: Record<string, unknown>;
  pricingDecision?: { feeCents: number } | null;
};

/** The decision is authoritative; MIN_FEE only covers subscriptions awaiting one. */
export function getFee(subscription: Subscription): number {
  return subscription.pricingDecision?.feeCents ?? MIN_FEE;
}

/** A new version carries its terms forward but must receive a fresh fee decision. */
export function newVersion(previous: Subscription) {
  const terms = { ...(previous.terms ?? {}) };
  // monthlyFeeCents was an approved decision stored on old terms. It is kept
  // readable for old records, but is not copied as the next version's decision.
  delete terms.monthlyFeeCents;
  return { terms, pricingDecision: null };
}

export function changedSinceApproval(subscription: Subscription): boolean {
  const approvedFee = subscription.pricingDecision?.feeCents;
  if (approvedFee === undefined) return false;
  const legacyFee = subscription.terms?.monthlyFeeCents;
  return typeof legacyFee === 'number' && approvedFee !== legacyFee;
}

/** Accept the legacy wire shape while validating its fee before persistence. */
export function acceptLegacyTerms(input: Record<string, unknown>) {
  if (!Number.isInteger(input.monthlyFeeCents)) throw new Error('invalid');
  return input;
}
